schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/ai-assisted-dev.json",
  "title": "AI-assisted development workflow record",
  "type": "object",
  "required": ["team", "owner", "inputs", "decision", "evidence", "review"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://"},
    "tool": {"type": "string", "enum": ["claude-code", "cursor", "copilot", "other", "ai-off"]},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "metrics": {
      "type": "object",
      "required": ["pr_count", "defect_escape_rate", "revert_rate", "churn_2w_rate"],
      "additionalProperties": false,
      "properties": {
        "pr_count": {"type": "integer", "minimum": 0},
        "defect_escape_rate": {"$ref": "#/definitions/rate"},
        "revert_rate": {"$ref": "#/definitions/rate"},
        "churn_2w_rate": {"$ref": "#/definitions/rate"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "team": {
      "type": "object",
      "required": ["name", "repo_url", "record_version"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 2},
        "repo_url": {"$ref": "#/definitions/url"},
        "record_version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 7,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "tool_task_map"}}}},
        {"contains": {"properties": {"name": {"const": "block_list"}}}},
        {"contains": {"properties": {"name": {"const": "context_files"}}}},
        {"contains": {"properties": {"name": {"const": "exclusion_file"}}}},
        {"contains": {"properties": {"name": {"const": "tool_retention"}}}},
        {"contains": {"properties": {"name": {"const": "prompt_template"}}}},
        {"contains": {"properties": {"name": {"const": "ai_assisted_label"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["tool_task_map", "block_list", "context_files", "exclusion_file", "tool_retention", "prompt_template", "ai_assisted_label"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "tool_task_map"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 7,
             "allOf": [
               {"contains": {"properties": {"task_class": {"const": "boilerplate-scaffolding"}}}},
               {"contains": {"properties": {"task_class": {"const": "unit-tests"}}}},
               {"contains": {"properties": {"task_class": {"const": "refactor"}}}},
               {"contains": {"properties": {"task_class": {"const": "code-review"}}}},
               {"contains": {"properties": {"task_class": {"const": "documentation"}}}},
               {"contains": {"properties": {"task_class": {"const": "data-migration"}}}},
               {"contains": {"properties": {"task_class": {"const": "infrastructure"}}}}
             ],
             "items": {
               "type": "object",
               "required": ["task_class", "tool", "checkpoint"],
               "additionalProperties": false,
               "properties": {
                 "task_class": {"type": "string", "enum": ["boilerplate-scaffolding", "unit-tests", "refactor", "code-review", "documentation", "data-migration", "infrastructure"]},
                 "tool": {"$ref": "#/definitions/tool"},
                 "checkpoint": {"type": "string", "enum": ["self-review", "one-reviewer", "two-reviewers-non-prompter", "ai-off"]}},
               "allOf": [
                 {"if": {"properties": {"tool": {"const": "ai-off"}}}, "then": {"properties": {"checkpoint": {"const": "ai-off"}}}},
                 {"if": {"properties": {"checkpoint": {"const": "ai-off"}}}, "then": {"properties": {"tool": {"const": "ai-off"}}}},
                 {"if": {"properties": {"task_class": {"enum": ["data-migration", "infrastructure"]}}}, "then": {"properties": {"checkpoint": {"enum": ["two-reviewers-non-prompter", "ai-off"]}}}}
               ]}}}}},
          {"if": {"properties": {"name": {"const": "block_list"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 8,
             "allOf": [
               {"contains": {"properties": {"area": {"const": "authentication-session"}}}},
               {"contains": {"properties": {"area": {"const": "authorization"}}}},
               {"contains": {"properties": {"area": {"const": "cryptography-keys"}}}},
               {"contains": {"properties": {"area": {"const": "payments-billing"}}}},
               {"contains": {"properties": {"area": {"const": "pii-processing"}}}},
               {"contains": {"properties": {"area": {"const": "secrets-config-loading"}}}},
               {"contains": {"properties": {"area": {"const": "production-iac"}}}},
               {"contains": {"properties": {"area": {"const": "database-migrations"}}}}
             ],
             "items": {
               "type": "object",
               "required": ["area", "paths", "policy"],
               "additionalProperties": false,
               "properties": {
                 "area": {"type": "string", "enum": ["authentication-session", "authorization", "cryptography-keys", "payments-billing", "pii-processing", "secrets-config-loading", "production-iac", "database-migrations", "other"]},
                 "paths": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 2}},
                 "policy": {"type": "string", "enum": ["ai-off", "two-reviewers-non-prompter"]}}}}}}},
          {"if": {"properties": {"name": {"const": "context_files"}}},
           "then": {"properties": {"value": {
             "type": "array",
             "items": {
               "type": "object",
               "required": ["tool", "path", "last_reviewed"],
               "additionalProperties": false,
               "properties": {
                 "tool": {"type": "string", "enum": ["claude-code", "cursor", "copilot", "other"]},
                 "path": {"type": "string", "pattern": "(CLAUDE\\.md|\\.cursor/rules|\\.cursorrules|\\.github/copilot-instructions\\.md|AGENTS\\.md)$"},
                 "last_reviewed": {"$ref": "#/definitions/date"}}}}}}},
          {"if": {"properties": {"name": {"const": "exclusion_file"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["path", "excludes"],
             "additionalProperties": false,
             "properties": {
               "path": {"type": "string", "pattern": "(\\.cursorignore|\\.claudeignore|\\.gitignore|\\.aiignore|\\.copilotignore)$"},
               "excludes": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 2}}}}}}},
          {"if": {"properties": {"name": {"const": "tool_retention"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 1,
             "items": {
               "type": "object",
               "required": ["tool", "terms_checked", "source"],
               "additionalProperties": false,
               "properties": {
                 "tool": {"type": "string", "enum": ["claude-code", "cursor", "copilot", "other"]},
                 "terms_checked": {"type": "boolean"},
                 "source": {"$ref": "#/definitions/url"},
                 "checked_on": {"$ref": "#/definitions/date"}}}}}}},
          {"if": {"properties": {"name": {"const": "prompt_template"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["path", "blocks"],
             "additionalProperties": false,
             "properties": {
               "path": {"type": "string", "minLength": 4},
               "blocks": {"type": "array", "const": ["Context", "Task", "Requirements", "Output"]}}}}}},
          {"if": {"properties": {"name": {"const": "ai_assisted_label"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["label", "auto_merge_disabled"],
             "additionalProperties": false,
             "properties": {
               "label": {"type": "string", "minLength": 4},
               "auto_merge_disabled": {"type": "boolean", "const": true}}}}}}
        ]
      }
    },
    "decision": {"type": "string", "minLength": 20, "pattern": "ai-off"},
    "evidence": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/url"}},
    "review": {
      "type": "object",
      "required": ["cadence", "next_review_at", "last_outcome"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
        "next_review_at": {"$ref": "#/definitions/date"},
        "last_outcome": {
          "oneOf": [
            {"type": "null"},
            {
              "type": "object",
              "required": ["period", "ai_assisted", "other", "worse_on", "map_tightened", "url"],
              "additionalProperties": false,
              "properties": {
                "period": {"type": "string", "minLength": 6},
                "ai_assisted": {"$ref": "#/definitions/metrics"},
                "other": {"$ref": "#/definitions/metrics"},
                "worse_on": {"type": "array", "items": {"type": "string", "enum": ["defect_escape_rate", "revert_rate", "churn_2w_rate"]}},
                "map_tightened": {"type": "boolean"},
                "action": {"type": "string", "minLength": 12},
                "url": {"$ref": "#/definitions/url"}
              },
              "if": {"properties": {"worse_on": {"minItems": 1}}},
              "then": {"required": ["action"], "properties": {"map_tightened": {"const": true}}}
            }
          ]
        }
      }
    }
  }
}

output-contract.example:
{
  "team": {"name": "billing-platform", "repo_url": "https://github.com/acme/billing", "record_version": "1.0.0"},
  "owner": "swe:bob",
  "inputs": [
    {"name": "tool_task_map", "value": [
      {"task_class": "boilerplate-scaffolding", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "unit-tests", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "refactor", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "code-review", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "documentation", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "data-migration", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "infrastructure", "tool": "copilot", "checkpoint": "one-reviewer"}
    ]},
    {"name": "block_list", "value": [
      {"area": "payments-billing", "paths": ["src/billing/charges/**"], "policy": "two-reviewers-non-prompter"}
    ]},
    {"name": "context_files", "value": []},
    {"name": "exclusion_file", "value": {"path": ".gitignore", "excludes": [".env"]}},
    {"name": "tool_retention", "value": [
      {"tool": "copilot", "terms_checked": false, "source": "https://github.com/features/copilot"}
    ]},
    {"name": "prompt_template", "value": {"path": "none", "blocks": ["Task"]}},
    {"name": "ai_assisted_label", "value": {"label": "", "auto_merge_disabled": false}}
  ],
  "decision": "We use Copilot for everything.",
  "evidence": ["https://github.com/acme/billing"],
  "review": {
    "cadence": "quarterly",
    "next_review_at": "2026-12-01",
    "last_outcome": {
      "period": "2026-Q2",
      "ai_assisted": {"pr_count": 80, "defect_escape_rate": 0.09, "revert_rate": 0.06, "churn_2w_rate": 0.31},
      "other": {"pr_count": 20, "defect_escape_rate": 0.04, "revert_rate": 0.02, "churn_2w_rate": 0.08},
      "worse_on": ["defect_escape_rate", "revert_rate", "churn_2w_rate"],
      "map_tightened": false,
      "url": "https://grafana.example.com/d/pr-quality"
    }
  }
}
